function validate(input) {
  const [arr] = input;
  if (!Array.isArray(arr) || arr.length < 1 || arr.length > 1000) return 'arr must hold 1 to 1000 items.';
  const leaves = new Set(), containers = new Set();
  const walk = (value, path, depth) => {
    if (value === null || typeof value !== 'object') {
      leaves.add(path);
      return null;
    }
    if (depth > 10) return 'Keep items at most 10 levels deep.';
    if (path !== '') containers.add(path);
    for (const key of Object.keys(value)) {
      if (!Array.isArray(value) && (key === '' || key.includes('.'))) return 'Object keys must be non-empty and contain no ".".';
      const error = walk(value[key], path === '' ? key : `${path}.${key}`, depth + 1);
      if (error) return error;
    }
    return null;
  };
  for (const item of arr) {
    if (item === null || typeof item !== 'object') return 'Each item of arr must be an object or an array.';
    const error = walk(item, '', 1);
    if (error) return error;
  }
  if (leaves.size > 1000) return 'Use at most 1000 distinct paths.';
  for (const path of leaves) if (containers.has(path)) return `The path "${path}" holds a value in one item and an object or array in another.`;
  return null;
}

