  const isContainer = (value) => value !== null && typeof value === 'object';
  const flatten = (value, prefix, row) => {
    for (const key of Object.keys(value)) {
      const path = prefix === '' ? key : `${prefix}.${key}`;
      if (isContainer(value[key])) {
        flatten(value[key], path, row);
      } else {
        row.set(path, value[key]);
      }
    }
    return row;
  };
  const rows = arr.map((item) => flatten(item, '', new Map()));
  const columns = new Set();
  for (const row of rows) {
    for (const path of row.keys()) {
      columns.add(path);
    }
  }
  const header = [...columns].sort();
  const matrix = [header];
  for (const row of rows) {
    matrix.push(header.map((path) => (row.has(path) ? row.get(path) : '')));
  }
  return matrix;
}

