function jsonToMatrix(arr) {
  // Collect every leaf path, then look each one up again in every item by walking its parts.
  const paths = [];
  const visit = (value, parts) => {
    if (value === null || typeof value !== 'object') {
      paths.push(parts.join('.'));
      return;
    }
    for (const key in value) visit(value[key], [...parts, key]);
  };
  for (const item of arr) for (const key in item) visit(item[key], [key]);
  const header = paths.filter((path, i) => paths.indexOf(path) === i).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  const lookup = (item, path) => {
    let value = item;
    for (const part of path.split('.')) {
      if (value === null || typeof value !== 'object' || !Object.hasOwn(value, part)) return '';
      value = value[part];
    }
    return value !== null && typeof value === 'object' ? '' : value;
  };
  return [header, ...arr.map(item => header.map(path => lookup(item, path)))];
}

