function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const names = small ? ['a', 'b', 'c'] : ['a', 'b', 'c', 'd', 'e', 'id', 'name', 'x', 'y', 'z', 'k1', 'k2', 'k10', 'ab', 'a0'];
  const maxDepth = small ? 2 : 4;
  // A schema fixes what each path holds, so no path is a plain value in one item and a container in another.
  // budget caps the number of leaf paths, which keeps the input and the matrix within the app's limits.
  let budget = small ? 6 : 40;
  const makeSchema = (depth, container) => {
    if (!container && (depth >= maxDepth || budget <= 1 || rand() < 0.5)) {
      budget -= 1;
      return null;
    }
    if (rand() < 0.25) {
      const length = 1 + Math.floor(rand() * (small ? 2 : 12));
      return { items: Array.from({ length }, () => makeSchema(depth + 1, false)) };
    }
    const keys = names.filter(() => rand() < (small ? 0.6 : 0.5));
    return { fields: keys.map(key => [key, makeSchema(depth + 1, false)]) };
  };
  const primitive = () => {
    const roll = rand();
    if (roll < 0.5) return Math.floor(rand() * 201) - 100;
    if (roll < 0.75) return pick(['', 'x', 'yes', 'no', 'a.b', 'Hello']);
    if (roll < 0.9) return rand() < 0.5;
    return null;
  };
  const build = (node) => {
    if (node === null) return primitive();
    if (node.items) return node.items.slice(0, Math.floor(rand() * (node.items.length + 1))).map(build);
    const object = {};
    for (const [key, child] of node.fields) if (rand() < 0.6) object[key] = build(child);
    return object;
  };
  const root = makeSchema(0, true);
  const count = small ? 1 + Math.floor(rand() * 4) : 200;
  return [Array.from({ length: count }, () => build(root))];
}
